-- Extensions beyond the default PostGIS image
CREATE EXTENSION IF NOT EXISTS "pgcrypto";
CREATE EXTENSION IF NOT EXISTS "citext";

-- Sensible defaults for a licensing database.
--   * UTC everywhere; the panel formats for display only
--   * identifiers are generated by the application, not sequences
ALTER DATABASE owneradmin SET timezone TO 'UTC';

-- Money is stored as integers of minor units, so guard against accidental
-- rounding at the database level.
DO $$
BEGIN
  EXECUTE 'CREATE SCHEMA IF NOT EXISTS app';
END $$;
